import React from 'react';
import {cva} from 'class-variance-authority';
const classes = cva("inline-flex items-center justify-center rounded font-medium disabled:opacity-50", {
  variants: {
    tone: {
      primary: "bg-action text-on-action",
      secondary: "bg-slate-100 text-slate-900",
    },
    size: {
      sm: "px-3 py-1 text-sm",
      lg: "px-4 py-2 text-base",
    },
  },
  defaultVariants: {tone: "primary", size: "sm"},
});
export default function ActionButton({tone,size,className,...props}) {
  return <button {...props} className={classes({tone: tone === undefined ? undefined : tone === "primary" ? "primary" : "secondary", size: size === undefined ? undefined : size === "sm" ? "sm" : "lg", className})}/>;
}

import React from 'react';
import {cva} from 'class-variance-authority';
const classes = cva("inline-flex rounded font-medium", {
  variants: {
    status: {
      idle: "bg-slate-100 text-slate-900",
      loading: "bg-amber-100 text-amber-900",
      success: "bg-green-100 text-green-900",
      error: "bg-red-100 text-red-900",
    },
    density: {
      compact: "px-1 py-0.5 text-xs",
      comfortable: "px-2 py-1 text-sm",
    },
  },
  defaultVariants: {status: "idle", density: "compact"},
});
export default function StatusBadge({status,density,className,...props}) {
  return <span {...props} className={classes({status: status === undefined ? undefined : ["idle", "loading", "success"].includes(status) ? status : "error", density: density === undefined ? undefined : density === "compact" ? "compact" : "comfortable", className})}/>;
}

import React from 'react';
