      action: "border-action bg-white",
    },
    density: {
      compact: "p-2",
      comfortable: "p-4",
    },
  },
  defaultVariants: {tone: "neutral", density: "comfortable"},
});
export default function PanelCard({tone,density,className,...props}) {
  return <section {...props} className={classes({tone: tone === undefined ? undefined : tone === "neutral" ? "neutral" : "action", density: density === undefined ? undefined : density === "compact" ? "compact" : "comfortable", className})}/>;
}

import assert from 'node:assert/strict';
