import test from 'node:test';
import {build} from 'esbuild';
import React from 'react';
import {renderToStaticMarkup} from 'react-dom/server';
import {compile} from '../runtime/node_modules/@tailwindcss/node/dist/index.mjs';

const built = await build({
  stdin: {
    contents: `export {default as ActionButton} from './ui/ActionButton.jsx';
export {default as PanelCard} from './ui/PanelCard.jsx';
export {default as StatusBadge} from './ui/StatusBadge.jsx';`,
    resolveDir: process.cwd(),
    sourcefile: 'ui-style-entry.jsx',
    loader: 'jsx',
  },
  bundle: true,
  platform: 'node',
  format: 'cjs',
  write: false,
  packages: 'external',
});
const componentModule = {exports: {}};
new Function('require', 'module', 'exports', built.outputFiles[0].text)(
  createRequire(import.meta.url), componentModule, componentModule.exports,
);
const {ActionButton, PanelCard, StatusBadge} = componentModule.exports;

function markup(Component, props, children = '내용') {
  return renderToStaticMarkup(React.createElement(Component, props, children));
}

test('CVA components preserve defaults, variants, children, native props and caller classes', () => {
  const button = markup(ActionButton, {type: 'submit', className: 'caller'});
  assert.match(button, /type="submit"/);
  assert.match(button, /bg-action text-on-action/);
  assert.match(button, /px-3 py-1 text-sm/);
  assert.match(button, /caller/);
  assert.match(button, />내용<\/button>/);

  const secondary = markup(ActionButton, {tone: 'secondary', size: 'lg', disabled: true});
  assert.match(secondary, /bg-slate-100 text-slate-900/);
  assert.match(secondary, /px-4 py-2 text-base/);
  assert.match(secondary, /disabled=""/);

  const panel = markup(PanelCard, {'aria-label': '재고', tone: 'action', density: 'compact', className: 'caller'});
  assert.match(panel, /aria-label="재고"/);
  assert.match(panel, /border-action bg-white/);
  assert.match(panel, /p-2/);
  assert.match(panel, /caller/);
  assert.match(panel, />내용<\/section>/);
  assert.match(markup(PanelCard, {}), /border-slate-200 bg-white[^\"]*p-4/);

  const badge = markup(StatusBadge, {status: 'loading', density: 'comfortable', title: '상태'});
  assert.match(badge, /bg-amber-100 text-amber-900/);
  assert.match(badge, /px-2 py-1 text-sm/);
  assert.match(badge, /title="상태"/);
  assert.match(markup(StatusBadge, {}), /bg-slate-100 text-slate-900[^\"]*px-1 py-0\.5 text-xs/);
  assert.match(markup(StatusBadge, {status: 'ready'}), /bg-red-100 text-red-900/);
});

test('Tailwind generates action utilities from the selected blue and white theme tokens', async () => {
  const engine = await compile(await readFile('theme.css', 'utf8'), {base: process.cwd(), onDependency() {}});
  const css = engine.build(['bg-action', 'text-on-action', 'border-action']);
  assert.match(css, /\.bg-action\s*\{[^}]*background-color:\s*var\(--color-blue-600\)/);
  assert.match(css, /\.text-on-action\s*\{[^}]*color:\s*var\(--color-white\)/);
  assert.match(css, /\.border-action\s*\{[^}]*border-color:\s*var\(--color-blue-600\)/);
});

